#define STYLE false

vec3 palette( in float t, in vec3 a, in vec3 b, in vec3 c, in vec3 d )
{
    return a + b*cos( 6.283185*(c*t+d) );
}


vec3 colorA = vec3(1.5); // contrast
vec3 colorB = vec3(1.7); // brightness
vec3 colorC = vec3(1.05); // phase so it has to be in int or .5 to be cont.
vec3 colorD = vec3(0.48, 1.144, 0.93); // main hues

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    vec2 grid = vec2(1.0, 10.0);
 uv/=1.-uv.y*0.5;

 uv*=mat2(cos(iTime),sin(iTime),-sin(iTime) ,cos(iTime));
 uv.x+=cos(iTime);
 uv.y+=sin(iTime);
 uv.y+=iTime;
  uv.x+=iTime;
    uv*=grid;
    vec2 ipos = floor(uv);
    vec2 fpos = fract(uv);
    vec3 col = vec3(0.);

      ipos+=grid;
        col = palette(fpos.x, colorA, colorB, colorC+1.5*smoothstep(tan(iTime), sin(-2.*3.14159*(ipos.x/grid.x)), sin(2.*3.14159*(ipos.y/grid.y)+iTime)), colorD);
        col *= step(0.05,fpos.x);
        col *= step(0.05,1.0 - fpos.y);
        col *= smoothstep(0., 0.15,fpos.x);



    // Output to screen
    fragColor = vec4(col*vec3(0.5,0.5,0.5),1.0);
}
